"""Load tickets generated by `replaybook generate`."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import yaml

from replaybook.adapters.redact import redact_ticket
from replaybook.schema.ticket import Ticket

TICKETS_FILE = "tickets.jsonl"
PLATFORM_FILE = "platform.yaml"


def load_tickets(data_dir: Path, redact: bool = True) -> list[Ticket]:
    path = Path(data_dir) / TICKETS_FILE
    tickets: list[Ticket] = []
    with path.open(encoding="utf-8") as handle:
        for line in handle:
            if line.strip():
                ticket = Ticket.model_validate(json.loads(line))
                tickets.append(redact_ticket(ticket) if redact else ticket)
    return tickets


def load_platform(data_dir: Path) -> dict[str, Any]:
    path = Path(data_dir) / PLATFORM_FILE
    if not path.exists():
        return {}
    return yaml.safe_load(path.read_text(encoding="utf-8")) or {}
